#!/usr/bin/env python3
"""Retain every native finding with a specific disposition; never waive it."""
import json,hashlib
from pathlib import Path
from collections import Counter
HERE=Path(__file__).resolve().parent
A={'annular_width': ('UNEXPECTED_REQUIRES_REVIEW', 'All J1 annular violations were cleared in R3; investigate any new occurrence.'), 'copper_edge_clearance': ('OPEN_USB_DFM_OR_PRECISION', 'J6 twelve pads end exactly at the USB cutout; GCT drawing recommends0.8mmPCB versus1.60252mm actual. Supplier/sample fit and copper-route tolerance remain open. Four SW2/SW3 arc gaps differ from0.3mm by under0.00003mm; numeric-boundary disposition is appropriate, not a global rule relaxation.'), 'footprint_type_mismatch': ('REVIEWED_MIXED_PAD_METADATA_NOT_WAIVED', 'Five mainboard SMT devices/connectors contain plated thermal vias or anchors. This is assembly metadata, not a proof of a short. Confirm mixed process perfootprint; J1 plated-signal connector and faceplate touch pad were corrected individually.'), 'lib_footprint_mismatch': ('OPEN_LIBRARY_RECONCILIATION', 'Embedded board footprint differs from library copy. Preserve routed geometry; compare deliberate edits before any library update.'), 'lib_footprint_issues': ('OPEN_LIBRARY_RECONCILIATION', 'Missing footprint library or library item does not erase the embedded board geometry. Restore a reproducible project-local mapping and compare geometry before updates.'), 'silk_edge_clearance': ('OPEN_SILK_DFM', 'Review clipped legend at routed edges in assembler CAM preview. Move nonessential artwork only in a separate PCB revision.'), 'silk_over_copper': ('OPEN_SILK_DFM', 'Review legend against solder-mask openings; keep pads clear and retain readable polarity/assembly markings.'), 'silk_overlap': ('OPEN_SILK_DFM', 'Resolve overlapping markings or accept the specific cosmetic overlap in CAM review.'), 'text_height': ('OPEN_SILK_DFM', 'Check actual text heights against selected supplier minimum; preserve useful assembly/programming labels.'), 'clearance': ('UNEXPECTED_REQUIRES_REVIEW', 'R3 native checks should have no clearance violations after jack correction and faceplate zone refill. Independently measured wheel gaps remain separately recorded because KiCad omits graphic-to-graphic checks.'), 'via_dangling': ('REVIEWED_INTENTIONAL_TEST_ACCESS', 'Via9beac3e6-1d53-440c-9527-78bfbd009e1f exactly coincides withTP7pad1 and connectsLED_ENABLE B.Cu routing. Preserve the plated top-side test access. See physical/handoff.json; no suppression added.'), 'copper_sliver': ('OPEN_WHEEL_ARTWORK_DFM', 'Deletion experiments locate the warning in SW2Pin3 polygon52a16c30-173a-482c-a962-efae53334f95. Preserve original shape pending CAM/etching and touch-geometry disposition; do not call it resolved.'), 'duplicate_footprints': ('OPEN_NONCOMPONENT_ANNOTATION', 'Anonymous REF** footprint identity conflicts are separate from component nets. Match UUIDs to graphic structures and set explicit board-only identity before cleanup.'), 'extra_footprint': ('OPEN_NONCOMPONENT_ANNOTATION', 'Anonymous board graphic footprint lacks a matching schematic component. Match UUID to the non-purchased inventory before annotating; do not delete it automatically.'), 'footprint_symbol_mismatch': ('UNEXPECTED_REQUIRES_REVIEW', 'J2 now matches FP Connector on PCB and schematic. Investigate any remaining mismatch.'), 'lib_symbol_issues': ('OPEN_SYMBOL_LIBRARY_RECONCILIATION', 'Corrected local symbol pin models are reviewed against primary manufacturer data and embedded copies. Remaining upstream KiCad library differences are not automatically circuit failures; preserve cached authoritative instances and compare before refreshing. See power/symbol-delta-audit evidence.'), 'power_pin_not_driven': ('UNEXPECTED_REQUIRES_REVIEW', 'R3 corrected rail models/source annotations should clear this class. Do not add another flag without tracing a real source.'), 'pin_to_pin': ('REVIEWED_MODE_DEPENDENT_OUTPUT_NOT_WAIVED', 'GND power flag conflicts with unused TPS22948 FLT open-drain output (error) and WM8523 SDOUT/DEEMPH bidirectional pin (warning). Keep manufacturer pin types; verify mode/strapping before accepting exact findings. No passive-pin retyping or blanket suppression.'), 'multiple_net_names': ('REVIEWED_ALIAS_NET_PARITY_PASSES', 'All 567 populated and non-populated electrical pin assignments reconcile between native netlists and PCB. Record the specific aliases and preserve intended connectivity during any label cleanup; this is not a general hidden-pin waiver.'), 'wire_dangling': ('UNEXPECTED_REQUIRES_REVIEW', 'Exactly three unused bus entries were removed; investigate new findings without changing circuit connectivity.'), 'starved_thermal': ('OPEN_LOCAL_THERMAL_REVIEW', 'Native GND refill exposes U15pad39 B.Cu thermal with1spoke versus2minimum at134.01,89mm. Nets reconcile and no unconnected items; inspect multilayer thermal/ground connection and assembly process before local geometry change or exact acceptance.')}
items=[];counts={}
for b in ('mainboard','faceplate'):
 d=json.loads((HERE/f'{b}-drc.json').read_text());e=json.loads((HERE/f'{b}-erc.json').read_text())
 for check,vs in [('DRC',d['violations']),('parity',d['schematic_parity']),('ERC',[v for s in e['sheets'] for v in s['violations']])]:
  counts[b+' '+check]=dict(Counter(v['severity'] for v in vs))
  for n,v in enumerate(vs):
   assert v['type'] in A,v['type']
   status,action=A[v['type']]
   identity=json.dumps([b,check,v],sort_keys=True)
   items.append({'id':hashlib.sha256(identity.encode()).hexdigest()[:16],'board':b,'check':check,'native_finding':v,'disposition':status,'required_action':action,'waived':False})
(HERE/'finding-dispositions.json').write_text(json.dumps({'status':'ALL_FINDINGS_RETAINED_NO_FABRICATION_RELEASE','counts':counts,'finding_count':len(items),'items':items},indent=2)+'\n')
print(json.dumps({'counts':counts,'findings_with_disposition':len(items)},indent=2))
